def moving_sums(values, k):
    if k <= 0 or k > len(values):
        return []
    if not values:
        return []
    result = []
    for i in range(len(values)):
        if i + k > len(values):
            break
        window_sum = sum(values[i:i + k])
        result.append(window_sum)
    return result

def moving_sums(values, k):
    if k <= 0 or k > len(values):
        return []
    if not values:
        return []
    return [sum(values[i:i + k]) for i in range(len(values) - k + 1)]

def expand_runs(pairs):
    if not pairs:
        return []
    result = []
    for value, count in pairs:
        if count == 0:
            continue
        result.extend([value] * count)
    return result

def dedup(items):
    seen = set()
    deduped = []
    for item in items:
        if item not in seen:
            seen.add(item)
            deduped.append(item)
    return deduped

def dedup(items):
    seen = set()
