def runs(values):
    if not values:
        return []
    result = []
    count = 1
    for i in range(1, len(values)):
        if values[i] == values[i - 1]:
            count += 1
        else:
            result.append((values[i - 1], count))
            count = 1
    result.append((values[-1], count))
    return result

def runs(values):
    if not values:
        return []
    result = []
    current_value = values[0]
    count = 1
    for value in values[1:]:
        if value == current_value:
            count += 1
        else:
            result.append((current_value, count))
            current_value = value
            count = 1
    result.append((current_value, count))
    return result

def lower_bound(a, x):
    left, right = (0, len(a))
    while left < right:
        mid = (left + right) // 2
        if a[mid] < x:
            left = mid + 1
        else:
            right = mid
    return left

