def balanced(s):
    """
    Check if all brackets in the string are balanced and correctly nested.
    Ignore all other characters.

    Parameters:
    s (str): The string to check.

    Returns:
    bool: True if all brackets are balanced and correctly nested, False otherwise.
    """
    stack = []
    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if char == ')' and top != '(' or (char == ']' and top != '[') or (char == '}' and top != '{'):
                return False
    return not stack
